      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(productA, 2);
    const result = await cart.checkout({ priceFetcher, asyncTaxProvider });
