    cart.add(productA, 1);
    await cart.checkout({ priceFetcher });
    // Internal state should retain original price
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(1000);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
    [999999, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects invalid percent %s", (percent, msg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(msg);
    });

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("computes 10% of 1000 = 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to nearest cent", () => {
      // 33% of 100 = 33.0 exactly
      const policy = new PercentageDiscountPolicy(33);
      expect(policy.computeDiscountCents(101)).toBe(33); // 33.33 → 33
    });

    it("floors fractional results", () => {
      // 15% of 999 = 149.85 → 149
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(999)).toBe(149);
    });

    it("100% returns full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "amountCents must be a non-negative integer"],
      [10.5, "amountCents must be a non-negative integer"],
    ])("rejects invalid amountCents %s", (amount, msg) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(msg);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns amountCents when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(300)).toBe(300);
    });

    it("returns exact subtotal when amount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy"
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum"
      );
      // 10% of 1000 = 100, fixed = 200, sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum"
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum"
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps individual negative policy results to 0", () => {
      const negativePolicy = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum"
      );
      // -50 clamped to 0, + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("can exceed subtotal (clamping is caller responsibility)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum"
      );
      // Each caps at min(600, 1000)=600, sum = 1200 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain"
      );
      // 10% of 1000 = 100, remaining = 900, fixed = min(200,900) = 200
      // total discount = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("second policy sees reduced remaining", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new PercentageDiscountPolicy(50)],
        "chain"
      );
      // fixed = min(800,1000) = 800, remaining = 200
      // 50% of 200 = 100, total = 900
      expect(composite.computeDiscountCents(1000)).toBe(900);
    });

    it("ordering matters in chain mode", () => {
      const policyA = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(100)],
        "chain"
      );
      const policyB = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100), new PercentageDiscountPolicy(50)],
        "chain"
      );
      // A: 50% of 1000=500, remaining=500, fixed=100 → total=600
      // B: fixed=100, remaining=900, 50% of 900=450 → total=550
      expect(policyA.computeDiscountCents(1000)).toBe(600);
      expect(policyB.computeDiscountCents(1000)).toBe(550);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain"
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("does not exceed original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "chain"
      );
      // first = min(600, 1000)=600, remaining=400
      // second = min(600, 400)=400, total=1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("clamps negative individual results to 0", () => {
      const negativePolicy = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain"
      );
      // max(0, -50) = 0, remaining stays 1000, fixed=100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });
});

