      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 99999)).toBe(999);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required"
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }])
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }])
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 500 }])
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }])
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            10.5
          )
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1
          )
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      expect(
        calc.computeShippingCents([makeLine("a", undefined, 2)], 1000)
      ).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      // weight = 400g → first bracket (≤500g) → 300
      expect(
        calc.computeShippingCents([makeLine("a", 200, 2)], 1000)
      ).toBe(300);
    });

    it("selects bracket at exact upper boundary", () => {
      // weight = 500g → first bracket (≤500g) → 300
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 1000)
      ).toBe(300);
    });

    it("selects next bracket when just over boundary", () => {
      // weight = 501g → second bracket (≤2000g) → 700
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 1000)
      ).toBe(700);
    });

    it("selects second bracket within range", () => {
      // weight = 1500g → second bracket (≤2000g) → 700
      expect(
        calc.computeShippingCents([makeLine("a", 750, 2)], 1000)
      ).toBe(700);
    });

    it("selects heaviest bracket at its boundary", () => {
      // weight = 5000g → third bracket (≤5000g) → 1200
      expect(
        calc.computeShippingCents([makeLine("a", 2500, 2)], 1000)
      ).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // weight = 6000g → overflow → 2000
      expect(
        calc.computeShippingCents([makeLine("a", 6000, 1)], 1000)
      ).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 3000, costCents: 1000 },
      ]);
      // weight = 5000g → no overflow → last bracket cost = 1000
      expect(
        noOverflow.computeShippingCents([makeLine("a", 5000, 1)], 1000)
      ).toBe(1000);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      // weight = 400g should still hit first sorted bracket (≤500g)
      expect(
        unordered.computeShippingCents([makeLine("a", 200, 2)], 1000)
      ).toBe(300);
    });
  });
});

