import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart — line management", () => {
  it("starts empty with 0 items", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
  });

  it("merges quantities when adding same product twice", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity to 0 removes product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity rejects negative", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 1)).toThrow(
      "Product unknown is not in the cart"
    );
  });

  it("clears all products", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("snapshot returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 1;
    // Internal state unchanged
    expect(cart.snapshot()[0]!.quantity).toBe(1);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(1000);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes subtotal from lines", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2 * 1000
    cart.add(productB, 1); // 1 * 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount policy", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 3); // subtotal = 3000
    const totals = cart.totals();
    expect(discount.computeDiscountCents).toHaveBeenCalledWith(3000);
    expect(totals.discountCents).toBe(500);
    expect(totals.totalCents).toBe(2500); // 3000 - 500
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped to subtotal
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("taxes the discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    // tax computed on discounted subtotal (1000 - 200 = 800)
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
    expect(totals.taxCents).toBe(80);
  });

  it("passes discounted subtotal to shipping calculator", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    // shipping receives discounted subtotal = 700
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      700
    );
    expect(totals.shippingCents).toBe(500);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(72),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    // discountedSubtotal = 900, total = 900 + 72 + 500 = 1472
    expect(totals.totalCents).toBe(1472);
  });

  it("uses custom region for tax", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(100),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

