describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy"
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum"
      );
      // 10% of 1000 = 100, fixed = 200, sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum"
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum"
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps individual negative policy results to 0", () => {
      const negativePolicy = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum"
      );
      // -50 clamped to 0, + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("can exceed subtotal (clamping is caller responsibility)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum"
      );
      // Each caps at min(600, 1000)=600, sum = 1200 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain"
      );
      // 10% of 1000 = 100, remaining = 900, fixed = min(200,900) = 200
      // total discount = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("second policy sees reduced remaining", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new PercentageDiscountPolicy(50)],
        "chain"
      );
      // fixed = min(800,1000) = 800, remaining = 200
      // 50% of 200 = 100, total = 900
      expect(composite.computeDiscountCents(1000)).toBe(900);
    });

    it("ordering matters in chain mode", () => {
      const policyA = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(100)],
        "chain"
      );
      const policyB = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100), new PercentageDiscountPolicy(50)],
        "chain"
      );
      // A: 50% of 1000=500, remaining=500, fixed=100 → total=600
      // B: fixed=100, remaining=900, 50% of 900=450 → total=550
      expect(policyA.computeDiscountCents(1000)).toBe(600);
      expect(policyB.computeDiscountCents(1000)).toBe(550);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain"
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("does not exceed original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "chain"
      );
